window.__finlexDocLoaded(157,{"id":157,"articles":[{"id":3970,"no":"全文","heading":"","text":"财会〔2022〕1号 人民银行、审计署、国资委、海关总署、税务总局、市场监管总局、银保监会、证监会、外汇局，各省、自治区、直辖市财政厅（局）： 为了贯彻落实《国务院办公厅关于进一步规范财务审计秩序 促进注册会计师行业健康发展的意见》（国办发〔2021〕30号）中“持续提升审计质量”和“完善审计准则体系”的要求，保持准则体系的内在一致性，中国注册会计师协会对《中国注册会计师鉴证业务基本准则》等11项准则进行了一致性修订。本次修订对其他相关准则涉及会计师事务所质量管理准则、特殊目的审计准则以及中国注册会计师职业道德守则的相应条款作出文字调整，不涉及实质性修订。现予印发，于发布之日起施行。 本批准则生效实施后，《财政部关于印发中国注册会计师执业准则的通知》（财会〔2006〕4号）、《财政部关于印发<中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求>等38项准则的通知》（财会〔2010〕21号）、《财政部关于印发<中国注册会计师审计准则第1504号——在审计报告中沟通关键审计事项>等12项准则的通知》（财会〔2016〕24号）以及《财政部关于印发<中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求>等18项审计准则的通知》（财会〔2019〕5号）中，相应的11项准则同时废止。 执行中有何情况和问题，请及时反馈中国注册会计师协会。 附件：1.中国注册会计师鉴证业务基本准则 2.中国注册会计师审计准则第1101号——注册会计师的总体目标和审计工作的基本要求 3.中国注册会计师审计准则第1111号——就审计业务约定条款达成一致意见 4.中国注册会计师审计准则第1131号——审计工作底稿 5.中国注册会计师审计准则第1151号——与治理层的沟通 6.中国注册会计师审计准则第1201号——计划审计工作 7.中国注册会计师审计准则第1401号——对集团财务报表审计的特殊考虑 8.中国注册会计师审计准则第1411号——利用内部审计人员的工作 9.中国注册会计师审计准则第1421号——利用专家的工作 10.中国注册会计师审计准则第1501号——对财务报表形成审计意见和出具审计报告 11.中国注册会计师审计准则第1503号——在审计报告中增加强调事项段和其他事项段 财政部 2022年1月5日","seq":0,"links":[{"doc_id":209,"tier":"L3","score":64,"rel_kind":"cites","target_seq":0,"target_art_no":"第一条","dir":"out","note":"正文显式引用《中国注册会计师鉴证业务基本准则（2022年1月5日修订）》"}]}]});
